function Logo({ inverted = false }: { inverted?: boolean }) {
  return <div className={`flex items-center gap-2.5 ${inverted ? 'text-[hsl(var(--sidebar-foreground))]' : ''}`}>
    <div className="grid h-8 w-8 place-items-center rounded-[10px] bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><span className="font-display text-lg font-extrabold tracking-[-.08em]">A</span></div>
    <div className="leading-none"><div className="font-display text-[15px] font-extrabold tracking-[.09em]">ARKA</div><div className="mt-1 font-mono text-[8px] uppercase tracking-[.16em] opacity-55">Operating system</div></div>
  </div>;
}

function Avatar({ name, size = 'md' }: { name: string; size?: 'sm' | 'md' | 'lg' }) {
  const initials = name.split(' ').map((part) => part[0]).join('').slice(0, 2);
  return <div className={`${size === 'sm' ? 'h-6 w-6 text-[9px]' : size === 'lg' ? 'h-11 w-11 text-sm' : 'h-8 w-8 text-[10px]'} grid shrink-0 place-items-center rounded-full bg-[#f7e7ad] font-bold text-[#6d5200]`}>{initials}</div>;
}

function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'yellow' | 'blue' | 'red' }) {
  const tones = { neutral: 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]', green: 'bg-[#fff0bd] text-[#6d5200]', yellow: 'bg-[#fff0bd] text-[#806400]', blue: 'bg-[#dce9f5] text-[#3b6787]', red: 'bg-[#f5ded8] text-[#a34b3b]' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.08em] ${tones[tone]}`}>{children}</span>;
}

function Button({ children, onClick, variant = 'primary', className = '', type = 'button', disabled = false }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; className?: string; type?: 'button' | 'submit'; disabled?: boolean }) {
  const variants = { primary: 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-sm hover:-translate-y-px', secondary: 'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))] hover:bg-[hsl(var(--muted))]', ghost: 'text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] hover:text-[hsl(var(--foreground))]', danger: 'bg-[#f5ded8] text-[#a34b3b]' };
  return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2.5 text-sm font-bold transition-all disabled:cursor-not-allowed disabled:opacity-50 ${variants[variant]} ${className}`}>{children}</button>;
}

function Card({ children, className = '', onClick }: { children: ReactNode; className?: string; onClick?: () => void }) {
  return <div onClick={onClick} className={`rounded-xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] shadow-[var(--shadow-sm)] ${onClick ? 'cursor-pointer transition hover:-translate-y-0.5 hover:shadow-[var(--shadow-md)]' : ''} ${className}`}>{children}</div>;
}

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="fixed inset-0 z-50 grid place-items-center bg-black/55 p-4 backdrop-blur-sm"><div className="max-h-[90dvh] w-full max-w-xl overflow-y-auto rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] p-6 shadow-2xl animate-rise"><div className="mb-5 flex items-center justify-between"><h2 className="font-display text-xl font-extrabold">{title}</h2><button onClick={onClose} className="rounded-lg p-2 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]"><X size={18} /></button></div>{children}</div></div>;
}

function Field({ label, placeholder, value, onChange, required = false, type = 'text' }: { label: string; placeholder?: string; value?: string; onChange?: (value: string) => void; required?: boolean; type?: string }) {
  return <label className="block space-y-1.5"><span className="text-xs font-bold text-[hsl(var(--muted-foreground))]">{label}{required ? ' *' : ''}</span><input required={required} type={type} value={value} onChange={(event) => onChange?.(event.target.value)} placeholder={placeholder} className="w-full rounded-lg border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 py-2.5 text-sm outline-none transition placeholder:text-[hsl(var(--muted-foreground))] focus:border-[hsl(var(--primary))] focus:ring-2 focus:ring-[hsl(var(--ring)/.15)]" /></label>;
}

function Progress({ value, color = 'bg-[hsl(var(--primary))]' }: { value: number; color?: string }) {
  return <div className="h-1.5 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className={`h-full rounded-full ${color}`} style={{ width: `${Math.min(100, value)}%` }} /></div>;
}

