  return <div className="min-h-[100dvh] bg-[hsl(var(--background))]">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[250px] flex-col border-r border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar))] p-4 text-[hsl(var(--sidebar-foreground))] transition-transform md:translate-x-0 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="mb-7 flex items-center justify-between px-2"><Logo inverted /><button onClick={() => setMobileOpen(false)} className="text-white/45 md:hidden"><X size={18} /></button></div>
      <div className="mb-7 rounded-xl border border-white/10 bg-white/5 p-3"><div className="mb-2 flex items-center justify-between"><span className="font-mono text-[9px] uppercase tracking-[.16em] text-white/45">Environment</span><Badge tone="yellow">Demo data</Badge></div><div className="flex items-center gap-2"><div className="grid h-7 w-7 place-items-center rounded-md bg-[#f7e7ad] text-[10px] font-extrabold text-[#6d5200]">AD</div><span className="text-sm font-bold">Arka Digital Media</span></div></div>
      <div className="mb-2 px-2 font-mono text-[9px] uppercase tracking-[.16em] text-white/35">Operate</div>
      <nav className="space-y-0.5">{navItems.map((item) => <NavItem key={item.href} item={item} active={location === item.href || (item.href !== '/dashboard' && location.startsWith(item.href))} />)}</nav>
      <div className="mt-auto space-y-1 border-t border-white/10 pt-3"><NavItem item={{ href: '/settings', label: 'Settings', icon: Settings2 }} active={location === '/settings'} /><button onClick={() => setRole(role === 'Founder' ? 'Team member' : role === 'Team member' ? 'Manager' : 'Founder')} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-white/60 transition hover:bg-white/10 hover:text-white"><RefreshCw size={16} /><span>Switch role</span><span className="ml-auto rounded bg-white/10 px-1.5 py-0.5 text-[9px] uppercase">{role}</span></button><button onClick={onLogout} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-white/45 hover:bg-white/10 hover:text-white"><X size={16} /><span>Sign out</span></button></div>
    </aside>
    {mobileOpen && <button className="fixed inset-0 z-30 bg-black/40 md:hidden" onClick={() => setMobileOpen(false)} aria-label="Close menu" />}
    <main className="md:pl-[250px]"><header className="sticky top-0 z-20 flex h-[70px] items-center justify-between border-b border-[hsl(var(--border))] bg-[hsl(var(--background)/.92)] px-5 backdrop-blur md:px-9"><div className="flex items-center gap-3"><button onClick={() => setMobileOpen(true)} className="rounded-lg p-2 hover:bg-[hsl(var(--muted))] md:hidden"><Menu size={19} /></button><div><div className="font-mono text-[9px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]">Tuesday · 15 September 2026</div><h1 className="font-display text-lg font-extrabold">{pageName}</h1></div></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2 text-xs text-[hsl(var(--muted-foreground))] md:flex"><Search size={14} /><span>Search work</span><span className="ml-4 rounded border border-[hsl(var(--border))] px-1.5 py-0.5 font-mono text-[9px]">⌘ K</span></div><button className="relative rounded-lg p-2.5 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]"><Bell size={18} /><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))]" /></button><Avatar name={role === 'Founder' ? 'Maya Chen' : role === 'Manager' ? 'Eli Brooks' : 'Noah Singh'} /></div></header><div className="mx-auto max-w-[1500px] p-5 md:p-9">{children}</div></main>
  </div>;
