function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 font-mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--primary))]">{eyebrow}</div><h2 className="font-display text-3xl font-extrabold tracking-[-.04em] md:text-4xl">{title}</h2>{description && <p className="mt-2 max-w-2xl text-sm text-[hsl(var(--muted-foreground))]">{description}</p>}</div>{action}</div>;
}

function Metric({ label, value, detail, icon: Icon, tone = 'normal' }: { label: string; value: string; detail: string; icon: typeof Activity; tone?: 'normal' | 'risk' }) {
  return <Card className={`p-4 md:p-5 ${tone === 'risk' ? 'border-[hsl(var(--accent))] bg-[#fff9e7]' : ''}`}><div className="flex items-start justify-between"><span className="text-xs font-bold text-[hsl(var(--muted-foreground))]">{label}</span><Icon size={16} className={tone === 'risk' ? 'text-[#806400]' : 'text-[hsl(var(--primary))]'} /></div><div className="mt-3 font-display text-2xl font-extrabold tracking-[-.04em] md:text-3xl">{value}</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">{detail}</div></Card>;
}

function DueLabel({ date }: { date: string }) {
  const overdue = date < TODAY;
  const today = date === TODAY;
  return <span className={overdue ? 'font-bold text-[#a34b3b]' : today ? 'font-bold text-[#806400]' : 'text-[hsl(var(--muted-foreground))]'}>{overdue ? 'Overdue' : today ? 'Due today' : `Due ${date.slice(5)}`}</span>;
}

function WorkRow({ item, onOpen }: { item: WorkItem; onOpen: () => void }) {
  return <button onClick={onOpen} className="grid w-full grid-cols-[1fr_auto] gap-4 border-b border-[hsl(var(--border))] px-5 py-4 text-left transition last:border-0 hover:bg-[hsl(var(--muted)/.45)] md:grid-cols-[1.3fr_.75fr_.65fr_110px]"><div className="min-w-0"><div className="flex items-center gap-2"><span className="truncate text-sm font-bold">{item.title}</span>{item.priority === 'Urgent' && <Flag size={13} className="shrink-0 text-[#a34b3b]" />}</div><div className="mt-1 flex flex-wrap gap-2 text-xs text-[hsl(var(--muted-foreground))]"><span>{item.workType}</span><span>·</span><span>{item.client || 'Internal'}</span></div></div><div className="hidden items-center gap-2 md:flex"><Avatar name={item.owner} size="sm" /><span className="text-xs font-medium">{item.owner}</span></div><div className="hidden items-center md:flex"><Badge tone={stageTone[item.stage]}>{item.stage}</Badge></div><div className="flex flex-col items-end gap-1 text-xs"><DueLabel date={item.dueDate} /><span className="text-[10px] text-[hsl(var(--muted-foreground))]">{item.progress}% complete</span></div></button>;
}

function CommandCenter({ work, activities, time, onOpen, onCreate }: { work: WorkItem[]; activities: ActivityItem[]; time: TimeEntry[]; onOpen: (id: string) => void; onCreate: () => void }) {
  const active = work.filter((item) => item.stage !== 'Completed');
  const dueToday = active.filter((item) => item.dueDate === TODAY);
  const overdue = active.filter((item) => item.dueDate < TODAY);
  const blocked = active.filter((item) => item.stage === 'Blocked');
  const review = active.filter((item) => item.stage === 'Review');
  const hours = time.reduce((sum, entry) => sum + entry.durationMinutes, 0) / 60;
  const workload = team.map((member) => ({ ...member, items: active.filter((item) => item.owner === member.name), minutes: time.filter((entry) => entry.user === member.name).reduce((sum, entry) => sum + entry.durationMinutes, 0) })).sort((a, b) => b.items.length - a.items.length);
  const attention = [...overdue.map((item) => ({ item, text: `${item.title} is overdue`, icon: ShieldAlert, tone: 'risk' as const })), ...blocked.map((item) => ({ item, text: `${item.title} is blocked`, icon: ShieldAlert, tone: 'risk' as const })), ...review.map((item) => ({ item, text: `${item.title} is waiting for review`, icon: MessageSquare, tone: 'normal' as const }))].slice(0, 5);
  return <><PageHeader eyebrow="Live operating view · Demo data" title="Founder Command Center" description="What is happening inside Arka right now — people, work, time, workload, and the exceptions that need a decision." action={<Button onClick={onCreate}><Plus size={16} /> New work item</Button>} />
    <div className="mb-7 grid grid-cols-2 gap-3 lg:grid-cols-5"><Metric label="Team active" value="7" detail="people with current work" icon={Users} /><Metric label="Active work" value={`${active.length}`} detail={`${work.filter((item) => item.stage === 'Completed').length} completed this cycle`} icon={Inbox} /><Metric label="Due today" value={`${dueToday.length}`} detail="deadline attention" icon={Clock3} tone={dueToday.length > 0 ? 'risk' : 'normal'} /><Metric label="Overdue" value={`${overdue.length}`} detail="work past deadline" icon={ShieldAlert} tone={overdue.length > 0 ? 'risk' : 'normal'} /><Metric label="Hours logged" value={`${hours.toFixed(1)}h`} detail="from task-linked entries" icon={Timer} /></div>
    <div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] px-5 py-4"><div><h3 className="font-display font-extrabold">Attention required</h3><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">Only the exceptions worth looking at now.</p></div><ShieldAlert size={17} className="text-[hsl(var(--primary))]" /></div><div className="divide-y divide-[hsl(var(--border))]">{attention.length ? attention.map(({ item, text, icon: Icon, tone }) => <button key={item.id} onClick={() => onOpen(item.id)} className="flex w-full items-start gap-3 p-4 text-left hover:bg-[hsl(var(--muted)/.45)]"><div className={`mt-0.5 rounded-md p-1.5 ${tone === 'risk' ? 'bg-[#fff0bd] text-[#806400]' : 'bg-[hsl(var(--muted))] text-[hsl(var(--primary))]'}`}><Icon size={14} /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold">{text}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{item.owner} · <DueLabel date={item.dueDate} /></div></div><ArrowRight size={14} className="mt-1 text-[hsl(var(--muted-foreground))]" /></button>) : <div className="p-8 text-center text-sm text-[hsl(var(--muted-foreground))]">No attention items right now.</div>}</div></Card>
      <Card className="p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-display font-extrabold">Work status</h3><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">Current stage distribution</p></div><KanbanSquare size={17} className="text-[hsl(var(--primary))]" /></div><div className="space-y-3">{stages.map((stage) => { const count = work.filter((item) => item.stage === stage).length; return <div key={stage} className="flex items-center gap-3"><span className="w-24 text-xs text-[hsl(var(--muted-foreground))]">{stage}</span><div className="flex-1"><Progress value={work.length ? count / work.length * 100 : 0} color={stage === 'Blocked' ? 'bg-[#a34b3b]' : stage === 'Completed' ? 'bg-[#806400]' : 'bg-[hsl(var(--primary))]'} /></div><b className="w-4 text-right text-xs">{count}</b></div>; })}</div></Card></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] px-5 py-4"><div><h3 className="font-display font-extrabold">Team workload</h3><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">Operational indicator · not an exact capacity calculation</p></div><Users size={17} className="text-[hsl(var(--primary))]" /></div><div className="divide-y divide-[hsl(var(--border))]">{workload.slice(0, 6).map((member) => <div key={member.name} className="grid grid-cols-[1.2fr_70px_70px_70px] items-center gap-3 px-5 py-3 text-xs"><div className="flex items-center gap-2"><Avatar name={member.name} size="sm" /><div><div className="font-bold">{member.name}</div><div className="text-[10px] text-[hsl(var(--muted-foreground))]">{member.role}</div></div></div><span>{member.items.length} active</span><span>{member.items.filter((item) => item.dueDate <= '2026-09-18').length} soon</span><span className={member.items.length >= 3 ? 'font-bold text-[#a34b3b]' : ''}>{(member.minutes / 60).toFixed(1)}h</span></div>)}</div></Card><Card className="overflow-hidden"><div className="border-b border-[hsl(var(--border))] px-5 py-4"><div className="flex items-center justify-between"><div><h3 className="font-display font-extrabold">Recent activity</h3><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">Meaningful work movement</p></div><Activity size={17} className="text-[hsl(var(--primary))]" /></div></div><div className="divide-y divide-[hsl(var(--border))]">{activities.slice(0, 5).map((entry) => <div key={entry.id} className="flex gap-3 p-4"><Avatar name={entry.by} size="sm" /><div className="text-xs leading-5"><b>{entry.by}</b> {entry.text}<div className="mt-1 font-mono text-[9px] uppercase text-[hsl(var(--muted-foreground))]">{entry.at}</div></div></div>)}</div></Card></div>
  </>;
}

function WorkInbox({ work, onOpen, onCreate }: { work: WorkItem[]; onOpen: (id: string) => void; onCreate: () => void }) {
  const [query, setQuery] = useState(''); const [filter, setFilter] = useState('All');
  const filtered = work.filter((item) => `${item.title} ${item.client || ''} ${item.owner} ${item.workType}`.toLowerCase().includes(query.toLowerCase())).filter((item) => filter === 'All' || item.stage === filter || (filter === 'Overdue' && item.dueDate < TODAY));
  return <><PageHeader eyebrow="All operational work · Demo data" title="Work inbox" description="One reliable place to see every work item, its owner, deadline, and current stage." action={<Button onClick={onCreate}><Plus size={16} /> New work item</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="flex flex-1 items-center gap-2 rounded-lg border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3"><Search size={16} className="text-[hsl(var(--muted-foreground))]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search work, client, owner, or type" className="w-full bg-transparent py-2.5 text-sm outline-none" /></div><select value={filter} onChange={(event) => setFilter(event.target.value)} className="rounded-lg border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3 py-2.5 text-xs font-bold outline-none"><option>All</option>{stages.map((stage) => <option key={stage}>{stage}</option>)}<option>Overdue</option></select></div><Card className="overflow-hidden"><div className="grid grid-cols-[1.3fr_.75fr_.65fr_110px] gap-4 border-b border-[hsl(var(--border))] px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-[hsl(var(--muted-foreground))]"><span>Work</span><span>Owner</span><span>Stage</span><span>Deadline</span></div>{filtered.map((item) => <WorkRow key={item.id} item={item} onOpen={() => onOpen(item.id)} />)}{filtered.length === 0 && <div className="p-12 text-center text-sm text-[hsl(var(--muted-foreground))]">No work matches those filters.</div>}</Card></>;
}

function WorkBoard({ work, onOpen, onCreate }: { work: WorkItem[]; onOpen: (id: string) => void; onCreate: () => void }) {
  return <><PageHeader eyebrow="Execution flow · Demo data" title="Work board" description="See work moving through the operating lifecycle. Open any card to update its stage, owner, time, and history." action={<Button onClick={onCreate}><Plus size={16} /> New work item</Button>} /><div className="flex gap-3 overflow-x-auto pb-4">{stages.map((stage) => <div key={stage} className="w-[260px] shrink-0"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[hsl(var(--primary))]" /><h3 className="text-sm font-bold">{stage}</h3></div><span className="grid h-6 min-w-6 place-items-center rounded-full bg-[hsl(var(--muted))] px-2 text-[10px] font-bold">{work.filter((item) => item.stage === stage).length}</span></div><div className="space-y-3">{work.filter((item) => item.stage === stage).map((item) => <Card key={item.id} onClick={() => onOpen(item.id)} className="p-4"><div className="mb-4 flex items-start justify-between gap-2"><Badge tone={stageTone[item.stage]}>{item.priority}</Badge><span className="font-mono text-[9px] text-[hsl(var(--muted-foreground))]">{item.dueDate.slice(5)}</span></div><h4 className="text-sm font-bold leading-5">{item.title}</h4><div className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{item.workType} · {item.client || 'Internal'}</div><div className="mt-4"><div className="mb-1 flex justify-between text-[10px] text-[hsl(var(--muted-foreground))]"><span>{item.owner}</span><b>{item.progress}%</b></div><Progress value={item.progress} /></div></Card>)}</div></div>)}</div></>;
}

function MyWork({ work, role, onOpen }: { work: WorkItem[]; role: Role; onOpen: (id: string) => void }) {
  const person = role === 'Founder' ? 'Maya Chen' : role === 'Manager' ? 'Eli Brooks' : 'Noah Singh';
  const mine = work.filter((item) => item.owner === person && item.stage !== 'Completed');
  const today = mine.filter((item) => item.dueDate === TODAY); const overdue = mine.filter((item) => item.dueDate < TODAY);
  return <><PageHeader eyebrow={`Personal queue · ${person}`} title="My work" description="A focused view of the work you own, what is due, and where your time is going." action={<Button variant="secondary"><ListFilter size={15} /> Filter</Button>} /><div className="mb-6 grid grid-cols-2 gap-3 sm:grid-cols-4"><Metric label="Active" value={`${mine.length}`} detail="owned work items" icon={Inbox} /><Metric label="Due today" value={`${today.length}`} detail="needs action" icon={Clock3} tone={today.length > 0 ? 'risk' : 'normal'} /><Metric label="Overdue" value={`${overdue.length}`} detail="past deadline" icon={ShieldAlert} tone={overdue.length > 0 ? 'risk' : 'normal'} /><Metric label="Focus" value="6.5h" detail="estimated today" icon={Timer} /></div><div className="grid gap-5 lg:grid-cols-3">{[['Due today', today], ['Upcoming', mine.filter((item) => item.dueDate > TODAY)], ['Recently completed', work.filter((item) => item.owner === person && item.stage === 'Completed')]].map(([label, items]) => <div key={label as string}><div className="mb-3 flex items-center justify-between"><h3 className="font-display font-extrabold">{label as string}</h3><span className="grid h-6 min-w-6 place-items-center rounded-full bg-[hsl(var(--muted))] px-2 text-[10px] font-bold">{(items as WorkItem[]).length}</span></div><div className="space-y-3">{(items as WorkItem[]).map((item) => <Card key={item.id} onClick={() => onOpen(item.id)} className="p-4"><div className="mb-4 flex items-start justify-between gap-2"><Badge tone={stageTone[item.stage]}>{item.stage}</Badge><DueLabel date={item.dueDate} /></div><h4 className="text-sm font-bold leading-5">{item.title}</h4><div className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{item.workType} · {item.client || 'Internal'}</div><div className="mt-4"><Progress value={item.progress} /></div></Card>)}</div>{(items as WorkItem[]).length === 0 && <Card className="p-7 text-center text-xs text-[hsl(var(--muted-foreground))]">No work here yet.</Card>}</div>)}</div></>;
}

function WorkDetail({ item, activities, time, running, onBack, onStage, onStart, onStop, onManual }: { item: WorkItem; activities: ActivityItem[]; time: TimeEntry[]; running: string | null; onBack: () => void; onStage: (stage: Stage, note?: string) => void; onStart: () => void; onStop: () => void; onManual: (minutes: number) => void }) {
  const [manualOpen, setManualOpen] = useState(false); const [minutes, setMinutes] = useState('60');
  const workTime = time.filter((entry) => entry.workId === item.id).reduce((sum, entry) => sum + entry.durationMinutes, 0);
  const itemActivities = activities.filter((entry) => entry.workId === item.id);
  return <><button onClick={onBack} className="mb-5 text-xs font-bold text-[hsl(var(--primary))]">← Back to work</button><div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-start"><div><div className="mb-2 flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.16em] text-[hsl(var(--primary))]"><span>{item.id}</span><span>·</span><span>{item.workType}</span></div><h2 className="max-w-3xl font-display text-3xl font-extrabold tracking-[-.04em]">{item.title}</h2><div className="mt-2 flex flex-wrap items-center gap-2 text-sm text-[hsl(var(--muted-foreground))]"><span>{item.client || 'Internal work'}</span><span>·</span><span>Owner: {item.owner}</span><Badge tone={stageTone[item.stage]}>{item.stage}</Badge></div></div><div className="flex flex-wrap gap-2">{running === item.id ? <Button variant="danger" onClick={onStop}><Timer size={15} /> Stop timer</Button> : <Button onClick={onStart}><Timer size={15} /> Start timer</Button>}<Button variant="secondary" onClick={() => setManualOpen(true)}><Plus size={15} /> Log time</Button></div></div><div className="mb-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><Metric label="Progress" value={`${item.progress}%`} detail="stage indicator" icon={BarChart3} /><Metric label="Priority" value={item.priority} detail="operational priority" icon={Flag} tone={item.priority === 'Urgent' ? 'risk' : 'normal'} /><Metric label="Estimated" value={`${(item.estimatedMinutes / 60).toFixed(1)}h`} detail="planned effort" icon={Clock3} /><Metric label="Actual" value={`${(workTime / 60).toFixed(1)}h`} detail="task-linked effort" icon={Timer} /></div><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="space-y-5"><Card className="p-5"><div className="mb-4 flex items-center justify-between"><div><h3 className="font-display font-extrabold">Work lifecycle</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Every transition is recorded in the activity history.</p></div><Command size={17} className="text-[hsl(var(--primary))]" /></div><div className="flex gap-2 overflow-x-auto pb-2">{stages.map((stage) => <button key={stage} onClick={() => onStage(stage)} className={`min-w-[92px] rounded-lg border px-3 py-3 text-left transition ${item.stage === stage ? 'border-[hsl(var(--primary))] bg-[#fff9e7]' : 'border-[hsl(var(--border))] hover:bg-[hsl(var(--muted))]'}`}><div className={`mb-2 h-2 w-2 rounded-full ${item.stage === stage ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--border))]'}`} /><div className="text-[10px] font-bold">{stage}</div><div className="mt-1 text-[9px] text-[hsl(var(--muted-foreground))]">{stageProgress[stage]}% typical</div></button>)}</div>{item.stage === 'Blocked' && <div className="mt-4 rounded-lg border border-[#ead998] bg-[#fff9e7] p-3 text-xs"><b>Blocked reason</b><p className="mt-1 text-[#806400]">{item.blockedReason || 'No reason recorded yet.'}</p></div>}</Card><Card className="p-5"><div className="mb-4 flex items-center justify-between"><div><h3 className="font-display font-extrabold">Description</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">The operational context for this work.</p></div><MoreHorizontal size={17} className="text-[hsl(var(--muted-foreground))]" /></div><p className="text-sm leading-7 text-[hsl(var(--muted-foreground))]">{item.description}</p><div className="mt-5 grid gap-4 border-t border-[hsl(var(--border))] pt-4 sm:grid-cols-3"><div><div className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Deadline</div><div className="mt-1 text-sm font-bold"><DueLabel date={item.dueDate} /></div></div><div><div className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Manager</div><div className="mt-1 text-sm font-bold">{item.manager || '—'}</div></div><div><div className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Created by</div><div className="mt-1 text-sm font-bold">{item.createdBy}</div></div></div></Card></div><div className="space-y-5"><Card className="p-5"><div className="mb-4 flex items-center justify-between"><h3 className="font-display font-extrabold">Activity history</h3><Activity size={16} className="text-[hsl(var(--primary))]" /></div><div className="space-y-4">{itemActivities.length ? itemActivities.map((entry) => <div key={entry.id} className="flex gap-3"><div className={`mt-1 h-2 w-2 shrink-0 rounded-full ${entry.tone === 'warning' ? 'bg-[#a34b3b]' : entry.tone === 'success' ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--border))]'}`} /><div className="text-xs leading-5"><b>{entry.by}</b> {entry.text}<div className="font-mono text-[9px] uppercase text-[hsl(var(--muted-foreground))]">{entry.at}</div></div></div>) : <div className="text-xs text-[hsl(var(--muted-foreground))]">No activity recorded yet.</div>}</div></Card><Card className="p-5"><div className="mb-4 flex items-center justify-between"><h3 className="font-display font-extrabold">Time entries</h3><Clock3 size={16} className="text-[hsl(var(--primary))]" /></div>{time.filter((entry) => entry.workId === item.id).map((entry) => <div key={entry.id} className="mb-3 flex items-center justify-between border-b border-[hsl(var(--border))] pb-3 last:mb-0 last:border-0 last:pb-0"><div className="flex items-center gap-2"><Avatar name={entry.user} size="sm" /><div className="text-xs font-bold">{entry.user}<div className="font-mono text-[9px] font-normal uppercase text-[hsl(var(--muted-foreground))]">{entry.startTime.slice(0, 10)}</div></div></div><span className="text-xs font-bold">{entry.durationMinutes}m</span></div>)}{time.filter((entry) => entry.workId === item.id).length === 0 && <div className="text-xs text-[hsl(var(--muted-foreground))]">No time entries yet.</div>}</Card></div></div>{manualOpen && <Modal title="Log manual time" onClose={() => setManualOpen(false)}><p className="mb-4 text-sm text-[hsl(var(--muted-foreground))]">Record effort already spent on this specific work item.</p><Field label="Minutes worked" value={minutes} onChange={setMinutes} type="number" required /><div className="mt-5 flex justify-end gap-2"><Button variant="secondary" onClick={() => setManualOpen(false)}>Cancel</Button><Button onClick={() => { onManual(Number(minutes)); setManualOpen(false); }}>Add time</Button></div></Modal>}</>;
}

function TeamPage({ work, onOpen }: { work: WorkItem[]; onOpen: (id: string) => void }) {
  return <><PageHeader eyebrow="People · Workload visibility" title="Team" description="Coordinate availability and workload without turning the system into surveillance." /><div className="grid gap-4 lg:grid-cols-2">{team.map((member) => { const mine = work.filter((item) => item.owner === member.name && item.stage !== 'Completed'); const indicator = mine.length >= 4 ? 'Overloaded' : mine.length >= 3 ? 'High' : mine.length ? 'Medium' : 'Low'; return <Card key={member.name} className="p-5"><div className="flex items-start gap-3"><Avatar name={member.name} size="lg" /><div className="min-w-0 flex-1"><div className="flex items-start justify-between"><div><h3 className="font-display font-extrabold">{member.name}</h3><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{member.role}</p></div><Badge tone={indicator === 'Overloaded' ? 'red' : indicator === 'High' ? 'yellow' : indicator === 'Low' ? 'green' : 'neutral'}>{indicator}</Badge></div><div className="mt-5 flex items-center justify-between text-xs"><span className="text-[hsl(var(--muted-foreground))]">{member.availability}</span><b>{mine.length} active work items</b></div><div className="mt-2"><Progress value={member.capacity} color={member.capacity > 80 ? 'bg-[#a34b3b]' : 'bg-[hsl(var(--primary))]'} /></div><div className="mt-4 flex flex-wrap gap-2">{mine.slice(0, 3).map((item) => <button key={item.id} onClick={() => onOpen(item.id)} className="rounded-md bg-[hsl(var(--muted))] px-2 py-1 text-left text-[10px] font-bold hover:bg-[#fff0bd]">{item.title}</button>)}</div></div></div></Card>; })}</div></>;
}

function TimePage({ work, time }: { work: WorkItem[]; time: TimeEntry[] }) {
  const total = time.reduce((sum, entry) => sum + entry.durationMinutes, 0); const byUser = team.map((member) => ({ ...member, minutes: time.filter((entry) => entry.user === member.name).reduce((sum, entry) => sum + entry.durationMinutes, 0) })).filter((member) => member.minutes > 0).sort((a, b) => b.minutes - a.minutes);
  return <><PageHeader eyebrow="Operational effort · Demo data" title="Time & effort" description="Where Arka's operational time is being spent, linked back to actual work." /><div className="mb-6 grid grid-cols-2 gap-3 sm:grid-cols-4"><Metric label="Today" value={`${(total / 60).toFixed(1)}h`} detail="task-linked effort" icon={Timer} /><Metric label="Entries" value={`${time.length}`} detail="recorded sessions" icon={Clock3} /><Metric label="Tracked work" value={`${new Set(time.map((entry) => entry.workId)).size}`} detail="work items with time" icon={Inbox} /><Metric label="Untracked" value="—" detail="not calculated yet" icon={Activity} /></div><div className="grid gap-5 lg:grid-cols-[.85fr_1.15fr]"><Card className="p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-display font-extrabold">Hours by person</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">This week</p></div><Users size={17} className="text-[hsl(var(--primary))]" /></div><div className="space-y-4">{byUser.map((member) => <div key={member.name}><div className="mb-1.5 flex items-center gap-2"><Avatar name={member.name} size="sm" /><span className="text-xs font-bold">{member.name}</span><span className="ml-auto text-xs font-bold">{(member.minutes / 60).toFixed(1)}h</span></div><Progress value={member.minutes / Math.max(...byUser.map((entry) => entry.minutes)) * 100} /></div>)}</div></Card><Card className="overflow-hidden"><div className="border-b border-[hsl(var(--border))] px-5 py-4"><h3 className="font-display font-extrabold">Time by work</h3></div><div className="divide-y divide-[hsl(var(--border))]">{work.filter((item) => time.some((entry) => entry.workId === item.id)).map((item) => { const minutes = time.filter((entry) => entry.workId === item.id).reduce((sum, entry) => sum + entry.durationMinutes, 0); return <div key={item.id} className="flex items-center gap-4 px-5 py-4"><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold">{item.title}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{item.owner} · {item.workType}</div></div><span className="text-sm font-bold">{(minutes / 60).toFixed(1)}h</span></div>; })}</div></Card></div></>;
}

function InsightsPage({ work, time }: { work: WorkItem[]; time: TimeEntry[] }) {
  const completed = work.filter((item) => item.stage === 'Completed'); const blocked = work.filter((item) => item.stage === 'Blocked'); const review = work.filter((item) => item.stage === 'Review'); const overdue = work.filter((item) => item.stage !== 'Completed' && item.dueDate < TODAY);
  return <><PageHeader eyebrow="Operational intelligence · Derived from work" title="Insights" description="Simple indicators from actual demo work data. No fabricated production metrics." /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Completion rate" value={`${Math.round(completed.length / work.length * 100)}%`} detail="of current work items" icon={CheckCircle2} /><Metric label="Blocked work" value={`${blocked.length}`} detail="needs an unblock decision" icon={ShieldAlert} tone={blocked.length ? 'risk' : 'normal'} /><Metric label="Awaiting review" value={`${review.length}`} detail="manager attention" icon={MessageSquare} tone={review.length ? 'risk' : 'normal'} /><Metric label="Overdue" value={`${overdue.length}`} detail="deadline risk" icon={Clock3} tone={overdue.length ? 'risk' : 'normal'} /></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><Card className="p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-display font-extrabold">Bottlenecks detected</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Exceptions based on current work state.</p></div><Zap size={17} className="text-[hsl(var(--primary))]" /></div><div className="space-y-3">{[{ label: 'Overdue work', value: overdue.length, detail: 'Items past their deadline' }, { label: 'Blocked work', value: blocked.length, detail: 'Items waiting on a dependency' }, { label: 'Review queue', value: review.length, detail: 'Items waiting for a decision' }, { label: 'Highest concentration', value: Math.max(...team.map((member) => work.filter((item) => item.owner === member.name && item.stage !== 'Completed').length)), detail: 'Active items held by one person' }].map((item) => <div key={item.label} className="flex items-center gap-4 rounded-lg bg-[hsl(var(--muted)/.55)] p-3"><div className="grid h-9 w-9 place-items-center rounded-lg bg-[#fff0bd] text-sm font-extrabold text-[#806400]">{item.value}</div><div><div className="text-sm font-bold">{item.label}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{item.detail}</div></div></div>)}</div></Card><Card className="p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-display font-extrabold">Stage flow</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Where work is accumulating.</p></div><KanbanSquare size={17} className="text-[hsl(var(--primary))]" /></div>{stages.map((stage) => <div key={stage} className="mb-3 flex items-center gap-3 last:mb-0"><span className="w-24 text-xs text-[hsl(var(--muted-foreground))]">{stage}</span><div className="flex-1"><Progress value={work.length ? work.filter((item) => item.stage === stage).length / work.length * 100 : 0} color={stage === 'Blocked' ? 'bg-[#a34b3b]' : 'bg-[hsl(var(--primary))]'} /></div><span className="w-5 text-right text-xs font-bold">{work.filter((item) => item.stage === stage).length}</span></div>)}</Card></div><Card className="mt-5 p-5"><div className="mb-4 flex items-center justify-between"><div><h3 className="font-display font-extrabold">Effort signal</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Actual time is calculated from task-linked entries.</p></div><Timer size={17} className="text-[hsl(var(--primary))]" /></div><div className="grid gap-4 sm:grid-cols-3"><div><div className="text-xs text-[hsl(var(--muted-foreground))]">Logged effort</div><div className="mt-1 font-display text-2xl font-extrabold">{(time.reduce((sum, entry) => sum + entry.durationMinutes, 0) / 60).toFixed(1)}h</div></div><div><div className="text-xs text-[hsl(var(--muted-foreground))]">Planned effort</div><div className="mt-1 font-display text-2xl font-extrabold">{(work.reduce((sum, item) => sum + item.estimatedMinutes, 0) / 60).toFixed(1)}h</div></div><div><div className="text-xs text-[hsl(var(--muted-foreground))]">Coverage</div><div className="mt-1 font-display text-2xl font-extrabold">{Math.round(time.reduce((sum, entry) => sum + entry.durationMinutes, 0) / work.reduce((sum, item) => sum + item.estimatedMinutes, 0) * 100)}%</div></div></div></Card></>;
}

function SettingsPage({ role, setRole }: { role: Role; setRole: (role: Role) => void }) {
  return <><PageHeader eyebrow="Workspace settings" title="Settings" description="Demo environment controls for the ARKA OS operating layer." /><div className="grid gap-5 lg:grid-cols-[.85fr_1.15fr]"><Card className="p-5"><div className="mb-5 flex items-center gap-3"><Avatar name={role === 'Founder' ? 'Maya Chen' : role === 'Manager' ? 'Eli Brooks' : 'Noah Singh'} size="lg" /><div><h3 className="font-display font-extrabold">{role === 'Founder' ? 'Maya Chen' : role === 'Manager' ? 'Eli Brooks' : 'Noah Singh'}</h3><p className="text-xs text-[hsl(var(--muted-foreground))]">{role} · Arka Digital Media</p></div></div><Button variant="secondary">Save profile</Button></Card><Card className="p-5"><h3 className="mb-5 font-display font-extrabold">Role preview</h3><div className="space-y-3">{(['Founder', 'Manager', 'Team member'] as Role[]).map((value) => <button key={value} onClick={() => setRole(value)} className={`flex w-full items-center justify-between rounded-lg border p-3 text-left ${role === value ? 'border-[hsl(var(--primary))] bg-[#fff9e7]' : 'border-[hsl(var(--border))] hover:bg-[hsl(var(--muted))]'}`}><span><b className="text-sm">{value}</b><span className="mt-1 block text-xs text-[hsl(var(--muted-foreground))]">{value === 'Founder' ? 'Organization-wide visibility' : value === 'Manager' ? 'Team execution visibility' : 'Own work and time visibility'}</span></span>{role === value && <Check size={16} className="text-[hsl(var(--primary))]\" />}</button>)}</div></Card></div></>;
}

function Login({ onEnter }: { onEnter: (role: Role) => void }) {
  const [role, setRole] = useState<Role>('Founder');
  return <div className="grid min-h-[100dvh] bg-[hsl(var(--background))] lg:grid-cols-[1.05fr_.95fr]"><div className="relative hidden overflow-hidden bg-[hsl(var(--sidebar))] p-10 text-white lg:flex lg:flex-col lg:justify-between"><div className="absolute inset-0 grid-paper opacity-[.08]" /><div className="relative"><Logo inverted /><div className="mt-28 max-w-xl"><div className="mb-5 inline-flex items-center gap-2 rounded-full border border-white/15 px-3 py-1.5 font-mono text-[10px] uppercase tracking-[.15em] text-white/65"><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))]" /> Internal operating system</div><h1 className="font-display text-6xl font-extrabold leading-[.98] tracking-[-.06em]">See the work.<br /><span className="text-[hsl(var(--accent))]">Move Arka forward.</span></h1><p className="mt-7 max-w-md text-base leading-7 text-white/60">ARKA OS turns daily work into a live view of ownership, deadlines, effort, workload, and what needs attention.</p></div></div><div className="relative flex items-end justify-between text-xs text-white/40"><span>ARKA DIGITAL MEDIA · OPERATING SYSTEM</span><span className="font-mono text-[10px]">DEMO / 09—26</span></div></div><div className="flex flex-col justify-center p-6 sm:p-10 lg:p-20"><div className="mb-14 lg:hidden"><Logo /></div><div className="mx-auto w-full max-w-[390px]"><div className="mb-10"><div className="mb-3 font-mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--primary))]">Welcome to ARKA OS</div><h2 className="font-display text-4xl font-extrabold tracking-[-.05em]">Know what is happening.</h2><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Choose a role to explore the operating view.</p></div><label className="block space-y-1.5"><span className="text-xs font-bold text-[hsl(var(--muted-foreground))]">Explore as</span><select value={role} onChange={(event) => setRole(event.target.value as Role)} className="w-full rounded-lg border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]"><option>Founder</option><option>Manager</option><option>Team member</option></select></label><Button onClick={() => onEnter(role)} className="mt-8 w-full py-3.5">Enter ARKA OS <ArrowRight size={16} /></Button><div className="mt-8 flex items-center gap-3 text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]"><div className="h-px flex-1 bg-[hsl(var(--border))]" />Demo data<div className="h-px flex-1 bg-[hsl(var(--border))]" /></div><p className="mt-7 text-center text-xs leading-5 text-[hsl(var(--muted-foreground))]">This workspace uses clearly labelled demo data.<br />Connect Supabase later for production accounts and persistence.</p></div></div></div>;
}

function AppRouter() {
  const [location, setLocation] = useLocation();
  const [role, setRole] = useState<Role>('Founder');
  const [signedIn, setSignedIn] = useState(false);
  const [work, setWork] = useState<WorkItem[]>(demoWork);
  const [activities, setActivities] = useState<ActivityItem[]>(demoActivities);
  const [time, setTime] = useState<TimeEntry[]>(demoTime);
  const [running, setRunning] = useState<{ workId: string; startedAt: number; user: string } | null>(null);
  const [timerTick, setTimerTick] = useState(Date.now());
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [, setCreateOpenState] = useState(false);
  const [newTitle, setNewTitle] = useState(''); const [newType, setNewType] = useState<WorkType>('Internal'); const [newOwner, setNewOwner] = useState('Noah Singh'); const [newDue, setNewDue] = useState('2026-09-25'); const [newPriority, setNewPriority] = useState<Priority>('Medium');
  useEffect(() => { if (!running) return; const interval = window.setInterval(() => setTimerTick(Date.now()), 1000); return () => window.clearInterval(interval); }, [running]);
  const selected = work.find((item) => item.id === selectedId) || null;
  const currentUser = role === 'Founder' ? 'Maya Chen' : role === 'Manager' ? 'Eli Brooks' : 'Noah Singh';
  const addActivity = (workId: string, text: string, tone: ActivityItem['tone'] = 'normal') => setActivities((all) => [{ id: `activity-${Date.now()}`, workId, text, by: currentUser, at: 'Just now', tone }, ...all]);
  const transition = (workId: string, stage: Stage) => { setWork((all) => all.map((item) => item.id === workId ? { ...item, stage, progress: stageProgress[stage], completedAt: stage === 'Completed' ? TODAY : item.completedAt } : item)); const item = work.find((entry) => entry.id === workId); if (item && item.stage !== stage) addActivity(workId, `moved ${item.title} from ${item.stage} to ${stage}`, stage === 'Blocked' || stage === 'Revision' ? 'warning' : stage === 'Completed' || stage === 'Approved' ? 'success' : 'normal'); };
  const startTimer = (workId: string) => { setRunning({ workId, startedAt: Date.now(), user: currentUser }); addActivity(workId, 'started a timer', 'normal'); };
  const stopTimer = () => { if (!running) return; const minutes = Math.max(1, Math.round((timerTick - running.startedAt) / 60000)); setTime((all) => [...all, { id: `time-${Date.now()}`, workId: running.workId, user: running.user, startTime: new Date(running.startedAt).toISOString(), endTime: new Date(timerTick).toISOString(), durationMinutes: minutes }]); addActivity(running.workId, `logged ${minutes} minutes of focused work`, 'success'); setRunning(null); };
  const addManualTime = (workId: string, minutes: number) => { if (!minutes || minutes < 1) return; setTime((all) => [...all, { id: `time-${Date.now()}`, workId, user: currentUser, startTime: new Date().toISOString(), endTime: new Date().toISOString(), durationMinutes: minutes }]); addActivity(workId, `logged ${minutes} minutes manually`, 'success'); };
  const createWork = () => { if (!newTitle.trim()) return; const id = `work-${Math.floor(Math.random() * 900) + 300}`; const item: WorkItem = { id, title: newTitle.trim(), description: 'New operational work item created in the demo workspace.', workType: newType, client: null, owner: newOwner, manager: role === 'Founder' ? 'Maya Chen' : currentUser, priority: newPriority, stage: 'Inbox', dueDate: newDue, estimatedMinutes: 240, progress: 5, createdBy: currentUser, createdAt: TODAY }; setWork((all) => [item, ...all]); setActivities((all) => [{ id: `activity-${Date.now()}`, workId: id, text: `created ${item.title} and assigned it to ${item.owner}`, by: currentUser, at: 'Just now' }, ...all]); setNewTitle(''); setCreateOpen(false); setSelectedId(id); setLocation(`/work/${id}`); };
  const setCreateOpen = (open: boolean) => { setCreateOpenState(open); if (open) setLocation('/work/new'); };
  if (!signedIn) return <Login onEnter={(nextRole) => { setRole(nextRole); setSignedIn(true); setLocation(nextRole === 'Team member' ? '/my-work' : '/dashboard'); }} />;
  if (location === '/work/new') return <Shell role={role} setRole={setRole} onLogout={() => { setSignedIn(false); setLocation('/'); }} activeCount={work.filter((item) => item.stage !== 'Completed').length}><CreateWorkModal onClose={() => { setCreateOpen(false); setLocation('/work'); }} onCreate={createWork} title={newTitle} setTitle={setNewTitle} type={newType} setType={setNewType} owner={newOwner} setOwner={setNewOwner} due={newDue} setDue={setNewDue} priority={newPriority} setPriority={setNewPriority} /></Shell>;
  if (selected) return <Shell role={role} setRole={setRole} onLogout={() => { setSignedIn(false); setSelectedId(null); setLocation('/'); }} activeCount={work.filter((item) => item.stage !== 'Completed').length}><WorkDetail item={selected} activities={activities} time={time} running={running?.workId === selected.id ? selected.id : null} onBack={() => { setSelectedId(null); setLocation('/work'); }} onStage={(stage) => transition(selected.id, stage)} onStart={() => startTimer(selected.id)} onStop={stopTimer} onManual={(minutes) => addManualTime(selected.id, minutes)} /></Shell>;
  return <Shell role={role} setRole={setRole} onLogout={() => { setSignedIn(false); setLocation('/'); }} activeCount={work.filter((item) => item.stage !== 'Completed').length}><Switch><Route path="/dashboard"><CommandCenter work={work} activities={activities} time={time} onOpen={(id) => { setSelectedId(id); setLocation(`/work/${id}`); }} onCreate={() => setCreateOpen(true)} /></Route><Route path="/my-work"><MyWork work={work} role={role} onOpen={(id) => { setSelectedId(id); setLocation(`/work/${id}`); }} /></Route><Route path="/work"><WorkInbox work={work} onOpen={(id) => { setSelectedId(id); setLocation(`/work/${id}`); }} onCreate={() => setCreateOpen(true)} /></Route><Route path="/board"><WorkBoard work={work} onOpen={(id) => { setSelectedId(id); setLocation(`/work/${id}`); }} onCreate={() => setCreateOpen(true)} /></Route><Route path="/team"><TeamPage work={work} onOpen={(id) => { setSelectedId(id); setLocation(`/work/${id}`); }} /></Route><Route path="/time"><TimePage work={work} time={time} /></Route><Route path="/insights"><InsightsPage work={work} time={time} /></Route><Route path="/settings"><SettingsPage role={role} setRole={setRole} /></Route><Route><CommandCenter work={work} activities={activities} time={time} onOpen={(id) => { setSelectedId(id); setLocation(`/work/${id}`); }} onCreate={() => setCreateOpen(true)} /></Route></Switch></Shell>;
}

function CreateWorkModal({ onClose, onCreate, title, setTitle, type, setType, owner, setOwner, due, setDue, priority, setPriority }: { onClose: () => void; onCreate: () => void; title: string; setTitle: (value: string) => void; type: WorkType; setType: (value: WorkType) => void; owner: string; setOwner: (value: string) => void; due: string; setDue: (value: string) => void; priority: Priority; setPriority: (value: Priority) => void }) {
  return <Modal title="Create new work item" onClose={onClose}><form onSubmit={(event) => { event.preventDefault(); onCreate(); }} className="space-y-4"><Field label="Work title" placeholder="e.g. Client onboarding system" value={title} onChange={setTitle} required /><label className="block space-y-1.5"><span className="text-xs font-bold text-[hsl(var(--muted-foreground))]">Work type</span><select value={type} onChange={(event) => setType(event.target.value as WorkType)} className="w-full rounded-lg border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 py-2.5 text-sm outline-none">{['Website', 'SEO', 'Social Media', 'Graphic Design', 'Meta Ads', 'Google Ads', 'Photography', 'Videography', 'Internal', 'Other'].map((value) => <option key={value}>{value}</option>)}</select></label><div className="grid gap-3 sm:grid-cols-2"><label className="block space-y-1.5"><span className="text-xs font-bold text-[hsl(var(--muted-foreground))]">Owner</span><select value={owner} onChange={(event) => setOwner(event.target.value)} className="w-full rounded-lg border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 py-2.5 text-sm outline-none">{team.map((member) => <option key={member.name}>{member.name}</option>)}</select></label><Field label="Deadline" value={due} onChange={setDue} type="date" required /></div><label className="block space-y-1.5"><span className="text-xs font-bold text-[hsl(var(--muted-foreground))]">Priority</span><select value={priority} onChange={(event) => setPriority(event.target.value as Priority)} className="w-full rounded-lg border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 py-2.5 text-sm outline-none">{['Low', 'Medium', 'High', 'Urgent'].map((value) => <option key={value}>{value}</option>)}</select></label><div className="flex justify-end gap-2 pt-3"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit" disabled={!title.trim()}>Create work item</Button></div></form></Modal>;
}

function App() {
  return <ErrorBoundary><QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter><AppRouter /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider></ErrorBoundary>;
}

export default App;